#!/bin/bash
set -euo pipefail
if [[ "$(id -u)" -ne 0 ]]; then
  echo "Not root yet."
  echo "Type: su - owner"
  echo "Password: clublink"
  echo "Then type: sudo bash /tmp/club-update.sh"
  exit 1
fi
python3 - << 'PY'
import base64, os
raw = """/opt/club-kiosk/kiosk_server.py

----
/opt/club-kiosk/kiosk-loop.sh

----
/var/lib/club-kiosk/firefox/user.js
"""
for block in raw.split("\n----\n"):
    path, _, data = block.partition("\n")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as handle:
        handle.write(base64.b64decode(data))
    if path.endswith(".py") or path.endswith(".sh"):
        os.chmod(path, 0o755)
    print("wrote", path)
PY
rm -f /var/lib/club-kiosk/firefox/sessionstore.jsonlz4 \
      /var/lib/club-kiosk/firefox/sessionstore.js \
      /var/lib/club-kiosk/firefox/sessionCheckpoints/recovery.jsonlz4 \
      /var/lib/club-kiosk/firefox/sessionCheckpoints/recovery.baklz4 || true
if command -v systemctl >/dev/null 2>&1; then
  systemctl restart club-kiosk-api.service || true
fi
apt-get update || true
apt-get install -y xterm || true
pkill -f /var/lib/club-kiosk/firefox || true
echo
echo "Done. Close this window."
echo "Hold Ctrl and Alt, tap S, then tap Change Wi-Fi."
